const pptxgen = require('pptxgenjs');
const fs = require('fs');
const path = require('path');

const pptx = new pptxgen();
pptx.layout = 'LAYOUT_16X9';
pptx.author = 'OpenAI';
pptx.company = 'OpenAI';
pptx.subject = 'Global burden of mental illness, prevalence, DALYs, treatment gap';
pptx.title = 'The Global Burden of Mental Illness: Prevalence, Impact, and the Treatment Gap';
pptx.lang = 'en-US';
pptx.theme = {
  headFontFace: 'Aptos Display',
  bodyFontFace: 'Aptos',
  lang: 'en-US'
};
pptx.defineLayout({ name: 'CUSTOM_WIDE', width: 10, height: 5.625 });
pptx.layout = 'CUSTOM_WIDE';
pptx.margin = 0;
pptx.defineSlideMaster({
  title: 'MASTER',
  background: { color: 'F6FAF9' },
  objects: []
});
pptx.slideWidth = 10;
pptx.slideHeight = 5.625;
pptx.defineChartColors(['006D77', '83C5BE', 'E29578', '4C5C68', 'B56576']);
pptx.defineLayout({ name: 'LAYOUT_16X9', width: 10, height: 5.625 });

const theme = {
  primary: '005C66',
  secondary: '218C8D',
  accent: 'E29578',
  accent2: '7A6C5D',
  light: 'DFF2F1',
  pale: 'EDF6F9',
  peach: 'FFDDD2',
  bg: 'F6FAF9',
  ink: '183642',
  muted: '5E747A',
  white: 'FFFFFF',
  line: 'B8D8D8',
  depression: '006D77',
  anxiety: '83C5BE',
  schizophrenia: 'E29578',
  bipolar: 'B56576',
  eating: '9A8C98',
};

const W = 10;
const H = 5.625;
const FONT_HEAD = 'Aptos Display';
const FONT_BODY = 'Aptos';

function addBg(slide) {
  slide.background = { color: theme.bg };
  slide.addShape(pptx.ShapeType.rect, { x: 0, y: 0, w: W, h: H, fill: { color: theme.bg }, line: { color: theme.bg } });
  slide.addShape(pptx.ShapeType.rect, { x: 0, y: 0, w: 0.16, h: H, fill: { color: theme.primary }, line: { color: theme.primary } });
  slide.addShape(pptx.ShapeType.arc, { x: 8.55, y: -0.9, w: 2.1, h: 2.1, adjustPoint: 0.15, line: { color: theme.light, transparency: 100 }, fill: { color: theme.light, transparency: 18 }, rotate: 0 });
}

function title(slide, text, opts = {}) {
  slide.addText(text, {
    x: opts.x ?? 0.55, y: opts.y ?? 0.32, w: opts.w ?? 8.7, h: opts.h ?? 0.52,
    fontFace: FONT_HEAD, fontSize: opts.size ?? 24, bold: true, color: opts.color ?? theme.ink,
    margin: 0, breakLine: false, fit: 'shrink'
  });
  if (opts.rule !== false) {
    slide.addShape(pptx.ShapeType.line, { x: opts.x ?? 0.55, y: (opts.y ?? 0.32) + 0.62, w: 1.05, h: 0, line: { color: theme.accent, width: 3 } });
  }
}

function foot(slide, n, text = 'Source: Our World in Data; IHME Global Burden of Disease (2025), 2023 data') {
  slide.addText(text, { x: 0.55, y: 5.16, w: 7.4, h: 0.18, fontFace: FONT_BODY, fontSize: 6.7, color: theme.muted, margin: 0 });
  slide.addShape(pptx.ShapeType.roundRect, { x: 9.28, y: 5.05, w: 0.42, h: 0.28, rectRadius: 0.04, fill: { color: theme.primary }, line: { color: theme.primary } });
  slide.addText(String(n).padStart(2,'0'), { x: 9.28, y: 5.105, w: 0.42, h: 0.13, fontFace: FONT_BODY, fontSize: 7.5, bold: true, align: 'center', color: theme.white, margin: 0 });
}

function pill(slide, text, x, y, w, color = theme.light, textColor = theme.primary) {
  slide.addShape(pptx.ShapeType.roundRect, { x, y, w, h: 0.28, rectRadius: 0.05, fill: { color }, line: { color, transparency: 100 } });
  slide.addText(text, { x: x + 0.08, y: y + 0.07, w: w - 0.16, h: 0.08, fontFace: FONT_BODY, fontSize: 7.5, bold: true, color: textColor, align: 'center', margin: 0 });
}

function statCard(slide, big, label, x, y, w, h, color) {
  slide.addShape(pptx.ShapeType.roundRect, { x, y, w, h, rectRadius: 0.07, fill: { color: theme.white }, line: { color: theme.line, width: 1.1 } });
  slide.addShape(pptx.ShapeType.rect, { x, y, w: 0.1, h, fill: { color }, line: { color } });
  slide.addText(big, { x: x + 0.2, y: y + 0.27, w: w - 0.4, h: 0.58, fontFace: FONT_HEAD, fontSize: 36, bold: true, color, margin: 0, align: 'center' });
  slide.addText(label, { x: x + 0.25, y: y + 1.02, w: w - 0.5, h: 0.43, fontFace: FONT_BODY, fontSize: 12.5, bold: true, color: theme.ink, margin: 0, align: 'center', fit: 'shrink' });
}

function callout(slide, text, x, y, w, h, color = theme.primary) {
  slide.addShape(pptx.ShapeType.roundRect, { x, y, w, h, rectRadius: 0.06, fill: { color: theme.pale }, line: { color: theme.light, width: 1 } });
  slide.addText(text, { x: x + 0.16, y: y + 0.12, w: w - 0.32, h: h - 0.22, fontFace: FONT_BODY, fontSize: 12, color, margin: 0, fit: 'shrink', breakLine: false, valign: 'mid' });
}

function addIcon(slide, x, y, label, color, shape = 'circle') {
  if (shape === 'circle') slide.addShape(pptx.ShapeType.ellipse, { x, y, w: 0.48, h: 0.48, fill: { color }, line: { color } });
  if (shape === 'diamond') slide.addShape(pptx.ShapeType.diamond, { x, y, w: 0.48, h: 0.48, fill: { color }, line: { color } });
  if (shape === 'rect') slide.addShape(pptx.ShapeType.roundRect, { x, y, w: 0.48, h: 0.48, rectRadius: 0.05, fill: { color }, line: { color } });
  slide.addText(label, { x: x + 0.01, y: y + 0.14, w: 0.46, h: 0.14, fontFace: FONT_BODY, fontSize: 10, bold: true, color: theme.white, align: 'center', margin: 0 });
}

function horizontalBar(slide, label, value, x, y, max, color, labelW = 2.25, barW = 5.7) {
  slide.addText(label, { x, y: y + 0.055, w: labelW, h: 0.18, fontFace: FONT_BODY, fontSize: 11.2, bold: true, color: theme.ink, margin: 0, fit: 'shrink' });
  slide.addShape(pptx.ShapeType.roundRect, { x: x + labelW + 0.12, y, w: barW, h: 0.28, rectRadius: 0.03, fill: { color: 'E7F0F0' }, line: { color: 'E7F0F0' } });
  const width = barW * value / max;
  slide.addShape(pptx.ShapeType.roundRect, { x: x + labelW + 0.12, y, w: width, h: 0.28, rectRadius: 0.03, fill: { color }, line: { color } });
  slide.addText(value.toFixed(1), { x: x + labelW + 0.24 + width, y: y + 0.055, w: 0.8, h: 0.16, fontFace: FONT_BODY, fontSize: 9.5, bold: true, color: theme.ink, margin: 0 });
}

function addPersonRows(slide, x, y, cols, total, filled, color) {
  const size = 0.13;
  const gap = 0.055;
  for (let i = 0; i < total; i++) {
    const row = Math.floor(i / cols);
    const col = i % cols;
    const fillColor = i < filled ? color : 'D8E5E5';
    slide.addShape(pptx.ShapeType.ellipse, { x: x + col * (size + gap), y: y + row * (size + gap), w: size, h: size, fill: { color: fillColor }, line: { color: fillColor } });
  }
}

function slide1() {
  const slide = pptx.addSlide('MASTER');
  slide.background = { color: theme.primary };
  slide.addShape(pptx.ShapeType.rect, { x: 0, y: 0, w: W, h: H, fill: { color: theme.primary }, line: { color: theme.primary } });
  slide.addShape(pptx.ShapeType.rect, { x: 6.65, y: 0, w: 3.35, h: H, fill: { color: '0A7580' }, line: { color: '0A7580' } });
  slide.addShape(pptx.ShapeType.arc, { x: 6.25, y: -0.55, w: 3.9, h: 3.9, fill: { color: theme.light, transparency: 72 }, line: { color: theme.light, transparency: 100 } });
  slide.addShape(pptx.ShapeType.arc, { x: 7.25, y: 2.35, w: 2.8, h: 2.8, fill: { color: theme.accent, transparency: 62 }, line: { color: theme.accent, transparency: 100 } });
  pill(slide, 'GLOBAL DATA • 2023', 0.75, 0.65, 1.55, theme.peach, theme.primary);
  slide.addText('The Global Burden of Mental Illness', { x: 0.75, y: 1.25, w: 6.05, h: 0.62, fontFace: FONT_HEAD, fontSize: 31, bold: true, color: theme.white, margin: 0, breakLine: false, fit: 'shrink' });
  slide.addText('Prevalence, Impact, and the Treatment Gap', { x: 0.75, y: 2.0, w: 6.0, h: 0.55, fontFace: FONT_HEAD, fontSize: 24, bold: true, color: 'DFF2F1', margin: 0, fit: 'shrink' });
  slide.addText('A data-driven overview for public health policy analysts and mental health program planners.', { x: 0.78, y: 2.92, w: 5.25, h: 0.46, fontFace: FONT_BODY, fontSize: 14.5, color: 'F6FAF9', margin: 0, breakLine: false, fit: 'shrink' });
  slide.addShape(pptx.ShapeType.line, { x: 0.78, y: 3.65, w: 2.3, h: 0, line: { color: theme.accent, width: 3 } });
  slide.addText('Source: Our World in Data — Mental Health\nAuthors: Dattani, Rodés-Guirao, Ritchie, and Roser (2023)\nData source: IHME, Global Burden of Disease (2025)', { x: 0.78, y: 4.05, w: 4.65, h: 0.56, fontFace: FONT_BODY, fontSize: 9.5, color: 'DFF2F1', margin: 0, breakLine: false, fit: 'shrink' });
  const ds = [694.6, 686.5, 210.2, 94.6, 47.5];
  const colors = [theme.depression, theme.anxiety, theme.schizophrenia, theme.bipolar, theme.eating];
  ds.forEach((v, i) => {
    slide.addShape(pptx.ShapeType.roundRect, { x: 7.13, y: 1.12 + i * 0.58, w: 1.7 * v / 694.6, h: 0.24, rectRadius: 0.03, fill: { color: colors[i] }, line: { color: colors[i] } });
  });
  slide.addText('DALYs per 100K\nacross five categories', { x: 7.08, y: 4.2, w: 2.15, h: 0.44, fontFace: FONT_BODY, fontSize: 10.2, bold: true, color: theme.white, margin: 0, align: 'center', fit: 'shrink' });
  foot(slide, 1, 'Source: Our World in Data; IHME Global Burden of Disease (2025)');
}

function slide2() {
  const slide = pptx.addSlide('MASTER'); addBg(slide);
